import { Component, OnInit } from '@angular/core';
import {
  Cart,
  CartItem,
  CartService
} from '../../services/cart.service';

@Component({
  selector: 'app-cart',
  templateUrl: './cart.component.html',
  styleUrls: ['./cart.component.css']
})
export class CartComponent implements OnInit {

  cart: Cart = {
    items: [],
    ingredients: []
  };

  // Controls Ingredients dropdown
  showIngredients = false;

  // Order success
  orderPlaced = false;

  orderedItems: CartItem[] = [];


  constructor(
    private cartService: CartService
  ) {}


  ngOnInit(): void {
    this.loadCart();
  }


  // ==========================================
  // LOAD CART
  // ==========================================

  loadCart(): void {

    this.cartService.getCart().subscribe({

      next: (data) => {
        this.cart = data;
      },

      error: (error) => {
        console.error(
          'Failed to load cart:',
          error
        );
      }

    });

  }


  // ==========================================
  // VEG / NON-VEG
  // ==========================================

  isNonVeg(type: string): boolean {

    const value = type
      ?.toLowerCase()
      .trim();

    return (
      value === 'non-veg' ||
      value === 'nonveg' ||
      value === 'non veg'
    );

  }


  // ==========================================
  // UPDATE PIZZA QUANTITY
  // ==========================================

  updateQuantity(
    itemId: string,
    quantity: number
  ): void {

    // If quantity becomes zero,
    // remove the pizza
    if (quantity === 0) {

      this.removeItem(itemId);

      return;
    }


    if (quantity < 1) {
      return;
    }


    this.cartService
      .updateQuantity(itemId, quantity)
      .subscribe({

        next: (data) => {
          this.cart = data;
        },

        error: (error) => {

          console.error(
            'Failed to update quantity:',
            error
          );

        }

      });

  }


  // ==========================================
  // REMOVE PIZZA
  // ==========================================

  removeItem(itemId: string): void {

    this.cartService
      .removeFromCart(itemId)
      .subscribe({

        next: (data) => {
          this.cart = data;
        },

        error: (error) => {

          console.error(
            'Failed to remove item:',
            error
          );

        }

      });

  }


  // ==========================================
  // TOGGLE INGREDIENTS
  // ==========================================

  toggleIngredients(): void {

    this.showIngredients =
      !this.showIngredients;

  }


  // ==========================================
  // PIZZA TOTAL
  // ==========================================

  getPizzaTotal(): number {

    return this.cart.items.reduce(
      (total, item) => {

        return total +
          (item.price * item.quantity);

      },
      0
    );

  }


  // ==========================================
  // INGREDIENT TOTAL
  // ==========================================

  getIngredientsTotal(): number {

    return this.cart.ingredients.reduce(
      (total, ingredient) => {

        return total +
          (ingredient.price * ingredient.quantity);

      },
      0
    );

  }


  // ==========================================
  // GRAND TOTAL
  // ==========================================

  getGrandTotal(): number {

    return (
      this.getPizzaTotal() +
      this.getIngredientsTotal()
    );

  }


  // ==========================================
  // PAY
  // ==========================================

  checkout(): void {

    if (
      this.cart.items.length === 0 &&
      this.cart.ingredients.length === 0
    ) {

      return;

    }


    // Save pizzas before clearing
    this.orderedItems = [
      ...this.cart.items
    ];


    this.cartService
      .clearCart()
      .subscribe({

        next: () => {

          this.cart = {
            items: [],
            ingredients: []
          };

          this.orderPlaced = true;

          this.showIngredients = false;

        },

        error: (error) => {

          console.error(
            'Failed to place order:',
            error
          );

        }

      });

  }


  // ==========================================
  // CLEAR CART
  // ==========================================

  clearCart(): void {

    this.cartService
      .clearCart()
      .subscribe({

        next: (data) => {

          this.cart = data;

          this.showIngredients = false;

        },

        error: (error) => {

          console.error(
            'Failed to clear cart:',
            error
          );

        }

      });

  }

}
